// Write the highlight translations as an export to tour-translations.ts
const existing = fs.readFileSync('lib/tour-translations.ts', 'utf8');

const highlightExport = `
export const highlightTranslations: Record<string, Record<string, string>> = ${JSON.stringify(highlightTranslations, null, 2)};

export function translateHighlight(highlight: string, language: string): string {
  if (language === "en") return highlight;
  return highlightTranslations[highlight]?.[language] || highlight;
}
`;

// Append after the existing getTranslatedTour function
const updated = existing + '\n' + highlightExport;
fs.writeFileSync('lib/tour-translations.ts', updated);
console.log('Added highlight translations');
